mapper.select:
SELECT 
FROM crawl_item i JOIN partner pt ON pt.code = i.partner_code
WHERE i.id = #{id}

mapper.update:
UPDATE crawl_item SET status = 'APPROVAL_REQUESTED', reviewer = #{reviewer}, reviewed_at = now(), reason = NULL, updated_at = now()
WHERE status = 'REVIEW_PENDING'
  AND id IN #{id}

UPDATE crawl_item SET status = 'EXCLUDED', reviewer = #{reviewer}, reviewed_at = now(), reason = #{reason}, updated_at = now()
WHERE status IN ('REVIEW_PENDING', 'APPROVAL_REQUESTED')
  AND id IN #{id}
